local alphabet = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
local function decode(input)
    input = input:gsub("[^" .. alphabet .. "=]", "")
    return (input:gsub(".", function(x)
        if x == "=" then return "" end
        local r, f = "", (alphabet:find(x, 1, true) or 1) - 1
        for i = 6, 1, -1 do r = r .. ((f % 2^i - f % 2^(i-1) > 0) and "1" or "0") end
        return r
    end):gsub("%d%d%d%d%d%d%d%d", function(x)
        local c = 0
        for i = 1, 8 do c = c + (x:sub(i,i) == "1" and 2^(8-i) or 0) end
        return string.char(c)
    end))
end
local source = decode(table.concat(data))
local compiler = loadstring or load
if not compiler then error("SonicHub: this executor does not support loadstring/load") end
local fn, err = compiler(source)
if not fn then error("SonicHub compile error: " .. tostring(err)) end
return fn()
